typeSystemExample.source:
#include <stdio.h>

#define max(a, b) ((a) > (b) ? (a) : (b))

int main(void) {
    printf("%d\n", max(3, 7));
    printf("%f\n", max(1.5, 2.8));
    return 0;
}

concurrencyExample.source:
#include <pthread.h>
#include <stdio.h>

long indices[4];
long results[4];

void *square(void *arg) {
    long i = *(long *)arg;
    results[i] = i * i;
    return NULL;
}

int main(void) {
    pthread_t t[4];
    for (long i = 0; i < 4; i++) {
        indices[i] = i;
        pthread_create(&t[i], NULL, square, &indices[i]);
    }
    for (int i = 0; i < 4; i++)
        pthread_join(t[i], NULL);
    for (int i = 0; i < 4; i++)
        printf("%ld ", results[i]);
    return 0;
}
